  function readProducts() {
    try {
      const raw = localStorage.getItem(storageKey);
      return raw ? JSON.parse(raw) : [];
    } catch (error) {
      return [];
    }
  }

  function mergeProducts(existingProducts) {
    const byId = new Map(existingProducts.map((product) => [product.id, product]));
    importedProducts.forEach((product) => {
      if (!byId.has(product.id)) byId.set(product.id, product);
    });
    return Array.from(byId.values());
  }

  window.trImportedProducts = importedProducts;

  try {
    const mergedProducts = mergeProducts(readProducts());
    localStorage.setItem(storageKey, JSON.stringify(mergedProducts));
  } catch (error) {
    console.warn("TR.tw ???????????", error);
  }
